// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzer will supply an arbitrary sender and arbitrary unlockTime and amount
    function testFuzz_property(address sender, uint256 unlockTime, uint256 value) public {
        // keep value within reasonable bounds so vm.deal works and avoid overflow in mappings
        value = bound(value, 0, 10 ether);
        // Ensure sender has funds to send
        vm.deal(sender, value);

        // move time to an arbitrary block timestamp to widen exploration
        // keep warp within reasonable range
        uint256 ts = bound(block.timestamp + 1 hours, 1, type(uint256).max);
        vm.warp(ts);

        // perform the Put call as the fuzzed sender, sending `value` wei
        vm.prank(sender);
        bool ok;
        try c.Put{value: value}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // Observe stored unlockTime for sender via public getter Acc
        // Acc is a public mapping to a struct; the compiler generates a getter Acc(address) -> (unlockTime, balance)
        (uint256 storedUnlock, uint256 storedBal) = c.Acc(sender);

        // General rule (single assertion): If the Put call succeeded, then the stored unlockTime is >= current block.timestamp
        // This must hold for the reference contract for all inputs, but the mutant can violate it for some inputs
        // We assert only when Put did not revert, because if Put reverted nothing changed.
        if (ok) {
            assertTrue(storedUnlock >= block.timestamp, "unlockTime must not be earlier than now");
        } else {
            // if Put reverted, still assert that storedUnlock is >= block.timestamp (it must hold as an invariant of reference)
            // but since revert means no state change, this is still valid: current storedUnlock (maybe 0) must be >= previous block.timestamp
            // to avoid false failure due to uninitialized zero vs block.timestamp > 0, only check that storedUnlock >= block.timestamp when ok==true
            // So for ok==false we do a vacuous true to keep single assertTrue rule: check storedUnlock >= 0
            assertTrue(storedUnlock >= 0);
        }
    }
}

