pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: actor who calls Put, the _unlockTime they pass, and the sent value
    function testFuzz_property(address actor, uint256 _unlockTime, uint256 value) public {
        // Keep domains wide but sensible: actor must be non-zero
        vm.assume(actor != address(0));
        // bound the value to a reasonable range to avoid out-of-gas in tests
        value = bound(value, 0, 10 ether);
        // Ensure actor has funds to send
        vm.deal(actor, value);

        // Actor calls Put with the fuzzed unlock time and value
        vm.prank(actor);
        c.Put{value: value}(_unlockTime);

        // Single assertion: stored unlockTime for actor is >= current block.timestamp
