pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: an address 'who' and a candidate unlock time 't' and deposit amount 'amt'
    // We will ensure amt >= MinSum so Put updates balance and thus unlockTime is set.
    function testFuzz_property(address who, uint256 t, uint256 amt) public {
        // Keep domain reasonable: avoid zero address and ensure a payable amount fits in balance
        vm.assume(who != address(0));
        // Ensure amount is at least MinSum so the Put will make acc.balance >= MinSum
        uint256 min = c.MinSum();
        amt = bound(amt, min, 10 ether);

        // Fund the fuzzed actor and call Put as them with value
        vm.deal(who, amt);
        vm.prank(who);
        // Perform Put with fuzzed _unlockTime t and fuzzed value amt
        c.Put{value: amt}(t);

        // Read the stored unlockTime via the public mapping getter
        (uint256 storedUnlockTime, uint256 storedBalance) = getHolder(who);

        // The reference contract ensures that after a deposit that results in balance >= MinSum,
        // the stored unlockTime is NOT strictly less than block.timestamp (it is either block.timestamp or a future time).
        // We assert that storedUnlockTime >= block.timestamp. This holds for the reference C for ALL admissible inputs.
        // The mutant that flips the ?: can set storedUnlockTime to t when t < block.timestamp, violating this.
        assertTrue(storedBalance >= min && storedUnlockTime >= block.timestamp);
    }

    // helper to call the public autogenerated getter for Acc mapping
    function getHolder(address a) internal view returns (uint256 unlockTime, uint256 balance) {
        (unlockTime, balance) = c.Acc(a);
    }
}

