pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: initialBalance and deposit attempt. We also fuzz the actor address.
    function testFuzz_property(uint256 initialBalance, uint256 deposit, address actor) public {
        // keep actor non-zero to be meaningful
        vm.assume(actor != address(0));
        // bound values to the 0..type(uint256).max range is already, but keep wide: allow full range

        // arrange: credit c.Acc[actor].balance by calling Put from actor with value = initialBalance
        vm.deal(actor, initialBalance);
        vm.prank(actor);
        // initial Put must succeed on reference implementation for all inputs (it had require preventing overflow)
        // Use try/catch to observe whether Put reverts. For the reference contract this should always succeed.
        bool ok1;
        try c.Put{value: initialBalance}(0) {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        // require the setup succeeded; if it didn't then the input is inadmissible for distinguishing
        vm.assume(ok1);

        // Now attempt the second deposit deposit from the same actor; this is the fuzzed action that may cause overflow.
        vm.deal(actor, deposit);
        vm.prank(actor);
        bool ok2;
        try c.Put{value: deposit}(0) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // General rule to assert: on the reference implementation, the second Put never reverts for ANY admissible inputs
        // (we ensured admissible by requiring the first Put succeeded). The buggy mutant removes the explicit require
        // and thus will revert when acc.balance + msg.value overflows under Solidity 0.8 semantics for some inputs.
        assertTrue(ok2);
    }
}

