pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: prior stored balance (as uint256) and incoming amount to Put
    function testFuzz_property(uint256 priorBalance, uint256 incoming) public {
        // Keep domain wide but ensure we can fund the actor
        address actor = address(0xABCD);
        // bind incoming to a payable-able amount (max ~1e30 is fine but keep within uint256)
        uint256 value = incoming;

        // We want to model a pre-existing stored acc.balance for actor in c.Acc[actor].
        // There is no direct setter, but we can simulate by calling Put from actor with priorBalance.
        // However Put itself may revert on mutant for the setup if overflow occurs; to ensure
        // setup uses the reference contract's behavior we perform the setup via this test process
        // using smaller steps: first ensure priorBalance fits by bounding to <= type(uint256).max/2
        // so that later adding incoming may overflow in mutant test runs.

        // bound priorBalance to a wide range but avoid extremely large values that prevent funding
        priorBalance = bound(priorBalance, 0, type(uint256).max/2);
        // incoming can be any uint256 (unbounded) — keep as-is

        // fund the actor so they can send value in Put
        vm.deal(actor, value + 1 ether);

        // First, set the actor's balance in the contract to priorBalance by calling Put from actor with that value
        vm.prank(actor);
        // this initial call uses priorBalance as msg.value
        try c.Put{value: priorBalance}(uint256(0)) {
            // initial setup succeeded
        } catch {
            // If this reverts, it means priorBalance itself overflowed against zero — shouldn't happen due to bound
            // but in case it does, skip this input by assuming false (reject case)
            vm.assume(false);
        }

        // Now call Put again with incoming value; capture whether it reverts.
        bool ok;
        vm.prank(actor);
        try c.Put{value: value}(uint256(0)) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assert): On the reference contract Put never reverts for any admissible inputs.
        // We enforce admissible domain by ensuring priorBalance was <= max/2 above. Under that domain,
        // the reference's require prevents overflow so Put must succeed; the mutant (without require)
        // may revert due to overflow on some inputs, so the fuzzer can find a case where ok==false.
        assertTrue(ok);
    }
}

