pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: priorBalance and sentValue. The property: Put should not revert for ANY admissible inputs
    // on the reference contract because it checks for overflow; the mutant can revert when the addition overflows.
    function testFuzz_property(uint256 priorBalance, uint256 sentValue) public {
        // Keep domain wide but ensure priorBalance is a valid stored balance we can set by simulating a prior Put.
        // We cannot directly write storage of c, so we simulate by calling Put from an address and sending ether.
        // Use an actor address for which we control funds.
        address actor = address(0xBEEF);

        // Bound sentValue to at most 2**250 to keep vm.deal feasible (but still large enough); keep wide.
        sentValue = bound(sentValue, 0, type(uint256).max);
        priorBalance = bound(priorBalance, 0, type(uint256).max);

        // Fund actor with enough Ether to perform two deposits if needed.
        uint256 fund = priorBalance + sentValue;
        if (fund < sentValue) fund = sentValue; // avoid overflow in local calculation
        // cap fund to a large but reasonable amount for the test environment
        uint256 cap = 1 ether * 1e6; // big cap but finite
        if (fund > cap) fund = cap;
        vm.deal(actor, fund);

        // First, ensure actor has priorBalance recorded in c.Acc by calling Put with that amount.
        vm.prank(actor);
        // try/catch to detect if the reference would ever revert here (it should not)
        bool ok1;
        try c.Put{value: priorBalance}(0) { ok1 = true; } catch { ok1 = false; }
        // If the first call reverted, shrink priorBalance so it succeeds (we want to establish the stored prior balance in admissible domain)
        if (!ok1) {
            // Reduce priorBalance to 0 and set up a zero prior balance state
            // (prank again with zero value)
            vm.prank(actor);
            try c.Put{value: 0}(0) { ok1 = true; } catch { ok1 = false; }
            priorBalance = 0;
            // Ensure actor still has funds for the main test
            vm.deal(actor, sentValue);
        }

        // Now perform the decisive call: attempt to call Put with sentValue and observe whether it reverts.
        vm.prank(actor);
        bool ok;
        try c.Put{value: sentValue}(0) { ok = true; } catch { ok = false; }

        // The reference contract ensures Put never reverts for any combination of prior stored balance and sentValue
        // because it explicitly checks for overflow; therefore ok must be true for all admissible inputs.
        // The mutant (without the require) will revert in cases where priorBalance + sentValue overflows under Solidity 0.8.
        assertTrue(ok);
    }
}

