pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: priorBalance and msgValue
    function testFuzz_property(uint256 priorBalance, uint256 msgValue) public {
        // Keep msgValue reasonably large but within uint256 range
        // Ensure priorBalance is settable to any uint256, and msgValue is not larger than type max (already true)
        // To create admissible domain: we allow all values, but we will set the on-chain stored balance to priorBalance
        // by writing through legitimate Put calls from an address we control. Use a helper to set balance directly
        // by calling Put with value priorBalance (bounded by deal). We need an actor to be the caller whose balance is in Acc.

        address actor = address(0xABCD);
        // ensure actor has enough ETH to send priorBalance and msgValue (cap to uint256 max for vm.deal)
        uint256 cap = type(uint256).max;
        // vm.deal uses uint256 but EVM has practical limits; in tests we can bound to 2**250 to be safe
        uint256 safeMax = uint256(1) << 250;
        if (priorBalance > safeMax) priorBalance = priorBalance % safeMax;
        if (msgValue > safeMax) msgValue = msgValue % safeMax;

        // Fund actor for both priorBalance (to seed stored balance) and msgValue (to test addition)
        uint256 totalFund = priorBalance + msgValue;
        if (totalFund < priorBalance) totalFund = type(uint256).max; // wrap, but after bounding unlikely
        vm.deal(actor, totalFund);

        // First, from actor, call Put to set stored balance = priorBalance
        vm.startPrank(actor);
        // call Put with value priorBalance to set stored balance
        c.Put{value: priorBalance}(0);
        vm.stopPrank();

        // Now perform the test call: calling Put with msgValue should succeed on reference whenever priorBalance + msgValue does not overflow
        bool ok;
        vm.startPrank(actor);
        try c.Put{value: msgValue}(0) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The reference guarantees that if priorBalance + msgValue does not overflow uint256 then Put does not revert.
        // We assert that condition: if addition does not overflow, Put must have returned ok==true.
        // Detect overflow by checking (priorBalance + msgValue) >= priorBalance (safe in bounded domain)
        // Use the stored public getter to read Acc[actor].balance and ensure it started as priorBalance before second Put
        // But we already advanced state; however the crucial assertion is only about the call returning when no overflow.

        // Compute overflow predicate in Solidity: addition overflows iff (priorBalance + msgValue) < priorBalance
        bool additionOverflow = (priorBalance + msgValue) < priorBalance;

        // If no overflow, reference must succeed, so ok must be true.
        assertTrue(!additionOverflow ? ok : true);
    }
}

