import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: priorBalance and deposit
    // We will arrange the contract's storage so that Acc[caller].balance == priorBalance
    // by performing an initial Put from the caller with that amount (if needed) and then
    // attempt another Put with deposit. We assert that the Put call on the reference
    // never reverts for any admissible fuzz inputs. The mutant (which removed the require)
    // will revert when priorBalance + deposit overflows uint256; the fuzzer can find such inputs.
    function testFuzz_property(uint256 priorBalance, uint256 deposit) public {
        // keep wide domain but avoid making the test impossible: allow any values
        address caller = address(0xBEEF);

        // Set up caller's balance so it can send 'priorBalance' + 'deposit' if necessary
        // but we only need to fund with deposit (and optionally initial priorBalance funding)
        // to allow the EOA to send the funds. Give large balance so vm.deal won't constrain us.
        vm.deal(caller, type(uint256).max);

        // Initialize stored prior balance by calling Put with priorBalance from caller
        // If priorBalance is zero this is a no-op but still establishes the storage entry.
        vm.prank(caller);
        c.Put{value: priorBalance}(0);

        // Now attempt the second Put with 'deposit' and capture whether it reverts
        bool ok;
        vm.prank(caller);
        try c.Put{value: deposit}(0) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: on the reference contract, Put never reverts for any inputs.
        // So we assert that this call succeeded. The mutant (without the pre-check) will
        // revert for some priorBalance+deposit overflow cases, causing this assertion to fail
        // for those fuzzed inputs.
        assertTrue(ok);
    }
}

