// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz deposit amount and depositor address. We check that after a single Put by an address
    // starting from zero recorded balance, Acc[addr].balance equals the msg.value sent.
    function testFuzz_property(uint256 amt, address depositor) public {
        // Keep amount within a wide but sensible range: not exceeding uint128 to avoid weird vm.deal limits
        amt = bound(amt, 0, 1 ether * 1000);
        // depositor must be non-zero
        vm.assume(depositor != address(0));

        // Ensure depositor has funds to send
        vm.deal(depositor, amt);

        // Record pre-state stored balance for depositor; require it to be zero to make the rule about a single deposit
        // Use the public getter Acc to read holder.balance: Acc(depositor).balance is accessible via c.Acc(depositor)
        // We require initial stored balance to be zero so the property is about a single Put call equal to msg.value
        (, uint256 preBal) = getHolder(depositor);
        vm.assume(preBal == 0);

        // Make the deposit from depositor
        vm.prank(depositor);
        c.Put{value: amt}(0);

        // After Put, the stored balance for depositor must equal the msg.value sent (amt).
        // This will hold for the reference implementation for all inputs; the mutant that adds +1 will cause
        // Acc[depositor].balance == amt + 1 for some fuzzed amt, making this assertion fail.
        (, uint256 postBal) = getHolder(depositor);
        assertTrue(postBal == amt);
    }

    // helper to read the public Acc mapping's Holder fields via the generated getter
    function getHolder(address a) internal returns (address, uint256) {
