    function testFuzz_property(uint128 depAmount, uint128 withdrawAmount, uint256 unlockOffset) public {
        // Keep values in wide but sensible bounds
        uint256 dep = bound(depAmount, 1, 10 ether);
        uint256 w = bound(withdrawAmount, 1, 10 ether);
        // pick an unlock time not too far in the past/future relative to now
        uint256 nowt = block.timestamp;
        uint256 unlock = nowt + bound(unlockOffset, 0, 3600);

        // Actor who will be the holder
        address actor = address(0xABCD);
        vm.deal(actor, dep);

        // 1) actor deposits via Put by sending Ether to fallback which calls Put(0) in reference; but Put requires unlocking time set by caller
        // Instead call Put directly by using the public Put via low-level call on the contract's ABI: we can't call Put with msg.sender other than actor
        // So we impersonate actor to call Put and set desired unlock time
        vm.startPrank(actor);
        // call Put with our desired unlock time and send deposit
        (bool s,) = address(c).call{value: dep}(abi.encodeWithSignature("Put(uint256)", unlock));
        require(s, "initial Put failed");
        vm.stopPrank();

        // Preconditions: ensure holder balance >= MinSum and >= requested withdraw amount
        // If deposit didn't reach MinSum, adjust by topping up actor balance and depositing more
        uint256 minSum = c.MinSum();
        if (dep < minSum || dep < w) {
            // top up so both conditions hold
            uint256 need = (minSum > dep ? minSum - dep : 0) + (w > dep ? w - dep : 0);
            vm.deal(actor, need);
            vm.startPrank(actor);
            (bool s2,) = address(c).call{value: need}(abi.encodeWithSignature("Put(uint256)", unlock));
            require(s2, "topup Put failed");
            vm.stopPrank();
        }

        // Advance time to exactly the unlock time boundary
        vm.warp(unlock);

        // Now attempt Collect at exactly block.timestamp == acc.unlockTime
        bool ok;
        vm.startPrank(actor);
        try c.Collect(w) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The reference contract requires block.timestamp > acc.unlockTime, so at equality the Collect must NOT succeed.
        // Therefore assertTrue(!ok) is the single assertion that should hold for the reference and be violated by the mutant.
        assertTrue(!ok);
    }
}

